12	
13	PRODUCT = "OpenSurvey"
14	RESOURCE = "surveys"
15	MAX_BODY_BYTES = 10 * 1024 * 1024
16	QUESTION_TYPES = ("text", "single_choice")
17	
18	PAGE = r"""<!doctype html>
19	<html lang="zh-CN">
20	<meta charset="utf-8">
21	<meta name="viewport" content="width=device-width,initial-scale=1">
22	<title>OpenSurvey · 问卷调查与反馈管理</title>
23	<style>
24	:root{--blue:#175b9c;--red:#c0392b;--grey:#666;--line:#d8dce3}
25	*{box-sizing:border-box}
26	body{font-family:system-ui,"PingFang SC","Microsoft YaHei",sans-serif;max-width:52rem;margin:2.5rem auto;padding:0 1rem;line-height:1.7;color:#1f2430}
27	a{color:var(--blue)}
28	h1{margin-bottom:.2rem}
29	h2{margin-top:2.2rem;border-bottom:1px solid var(--line);padding-bottom:.3rem}
30	.muted{color:var(--grey);font-size:.92rem}
31	ul.plain{list-style:none;padding-left:0}
32	ul.plain li{padding:.25rem 0;border-bottom:1px dashed var(--line)}
33	form label{display:block;margin:1rem 0 .25rem;font-weight:600}
34	input[type=text],textarea{width:100%;padding:.5rem .6rem;border:1px solid var(--line);border-radius:.35rem;font:inherit}
35	textarea{resize:vertical}
36	/* 标题与选项允许内部换行：用随内容增高的 textarea 展示，不能压成单行输入框 */
37	textarea.grow{resize:none;overflow:hidden;min-height:2.4rem;line-height:1.5}
38	.card{border:1px solid var(--line);border-radius:.5rem;padding:1rem 1.2rem;margin:1rem 0;background:#fafbfd}
39	.q-head{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;margin-bottom:.5rem}
40	.q-index{font-weight:700}
41	.tag{font-size:.8rem;background:#e8f0fa;color:var(--blue);border-radius:1rem;padding:.05rem .6rem}
42	.tag.required{background:#fdecea;color:var(--red)}
43	.req{margin:0;font-weight:400;display:flex;align-items:center;gap:.3rem}
44	.spacer{flex:1}
45	button{font:inherit;cursor:pointer}
46	.btn{border:1px solid var(--blue);background:var(--blue);color:#fff;border-radius:.35rem;padding:.45rem 1.1rem;text-decoration:none;display:inline-block}
47	.btn.secondary{background:#fff;color:var(--blue)}
48	.link{border:none;background:none;color:var(--blue);padding:0;font-size:.92rem}
49	.link.danger{color:var(--red)}
50	.row-actions{display:flex;gap:.8rem;flex-wrap:wrap;margin-top:1.2rem}
51	.opt-row{display:flex;align-items:center;gap:.6rem;margin:.4rem 0}
52	.opt-index{color:var(--grey);font-size:.9rem;min-width:3.2rem}
53	.banner{border:1px solid var(--red);background:#fdf3f2;color:var(--red);border-radius:.5rem;padding:.7rem 1rem;margin:1rem 0;white-space:normal}
54	.banner ul{margin:.4rem 0 0;padding-left:1.2rem}
55	.banner button{color:var(--red);text-decoration:underline;background:none;border:none;padding:0;text-align:left}
56	/* 保存状态条：与错误提示条区分开，明确“刚才那次提交已保存”与“还有未保存修改” */
57	.save-status{margin:1rem 0;display:flex;flex-direction:column;gap:.5rem}
58	.save-status[hidden]{display:none}
59	.save-note{border-radius:.5rem;padding:.7rem 1rem;white-space:normal}
60	.save-note.saved{border:1px solid #1e7e45;background:#ecf7f0;color:#155c33}
61	.save-note.dirty{border:1px solid #9a6d12;background:#fdf6e3;color:#7a5207}
62	/* 等待保存结果：蓝色中性提示，与成功（绿）、未保存（黄）、错误（红）区分 */
63	.save-note.saving{border:1px solid var(--blue);background:#eef4fb;color:#144a80}
64	button:disabled{opacity:.55;cursor:not-allowed}
65	.field-err{color:var(--red);font-size:.85rem;margin:.25rem 0 0;min-height:1px}
66	.invalid{border-color:var(--red)!important;background:#fdf6f5}
67	.detail-meta{color:var(--grey);font-size:.9rem}
68	.detail-desc,.opt-text-display{white-space:pre-wrap}
69	/* 标题中被接口保留的内部换行在列表与详情中也要原样显示 */
70	h2,.q-list .q-line,ul.plain a{white-space:pre-wrap}
71	.q-list>li{margin:1rem 0}
72	.q-list .q-line{font-weight:600}
73	.q-list ol{margin:.4rem 0 0 1.4rem}
74	</style>
75	<main>
76	<h1>OpenSurvey</h1>
77	<p>问卷调查与反馈管理</p>
78	<div id="app"></div>
79	<p class="muted"><a href="/api/surveys">问卷列表接口</a> · <a href="/health">服务状态</a></p>
80	</main>
81	<script>
82	"use strict";
83	const app = document.getElementById("app");
84	
85	// 每次进入一个页面都开启新一代视图：切换首页/详情/编辑、重新进入同一份问卷、
86	// 重试加载以及浏览器前进/后退都会使代数递增。较早一代页面发起的请求再晚
87	// 返回也必须丢弃，不能覆盖用户当前所在页面。
88	let activeView = 0;
89	
90	// 首尾裁剪必须与接口（Python str.strip()）逐字符一致，网页校验、提交内容与
91	// “是否还有未保存修改”的比较才能表达同一份文本含义。JS 原生 trim() 的字符集
92	// 恰好不同：它会裁掉 U+FEFF（接口保留该字符），却不裁 U+0085 与 U+001C–
93	// U+001F（接口会把它们当空白裁掉）。这里显式列出接口会裁的 29 个字符，
94	// U+FEFF 刻意不在其中；内部字符（含内部换行）一律不动。说明字段从不裁剪。
95	const API_TRIM_CLASS =
96	  "\\t\\n\\v\\f\\r\\x1c-\\x1f\\x20\\u0085\\u00a0\\u1680" +
97	  "\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000";
98	const apiTrimRe = new RegExp(
99	  "^[" + API_TRIM_CLASS + "]+|[" + API_TRIM_CLASS + "]+$", "g");
100	function apiTrim(value) { return value.replace(apiTrimRe, ""); }
101	
102	// 换行归一化：接口会原样保留文本内部的回车换行（CRLF，\r\n）、单独回车
103	// （CR，\r）与换行（LF，\n），但这些值赋给 textarea 后会被浏览器立即统一
104	// 成 LF（实测在赋值给 .value 的那一刻即发生）。因此编辑页必须在把原稿送进
105	// 输入框之前记录原始字符串，保存时再按“可见内容是否改变”决定还原原稿还是
106	// 采用当前输入；比较一律基于归一化为 LF 的文本，使三种换行在编辑框里的同
107	// 一份可见内容被视为“没有改变”。
108	function normalizeNL(value) { return value.replace(/\r\n|\r|\n/g, "\n"); }
109	
110	// 仅编辑模式使用：输入框元素 -> 打开编辑页时该字段从接口读到的原始字符串。
111	// 用 WeakMap 是为了让随题目/选项删除而移除的元素连同记录一起被回收，绝不
112	// 需要手工清理，也不会把已删除行的原文错配到后来顶上来的另一行。新建模式
113	// 下不写入任何记录。
114	const origMap = new WeakMap();
115	function rememberOriginal(el, raw) { origMap.set(el, String(raw)); }
116	
117	// 计算一个文本字段“实际要保存”的字符串：
118	// - 编辑模式且该字段可见内容与打开时一致：还原为原稿，保留原始 CRLF/CR/LF；
119	// - 其余情况（真正修改过，或新建模式）：采用输入框当前文本（浏览器统一为 LF）。
120	// 比较规则与“判断文字是否改变”的既有规则一致：trimFields 为真时（问卷标题、
121	// 题目标题、选项）首尾空白不参与比较，因此只增删首尾空白也算未改变、仍还原
122	// 原稿（原稿内部的 CRLF/CR 不会因此被 LF 覆盖）；说明字段不裁剪，逐字符比较。
123	function resolveFieldValue(el, {trimFields = false} = {}) {
124	  const current = el.value;
125	  const original = origMap.get(el);
126	  if (original !== undefined) {
127	    const a = trimFields ? apiTrim(normalizeNL(current)) : normalizeNL(current);
128	    const b = trimFields ? apiTrim(normalizeNL(original)) : normalizeNL(original);
129	    if (a === b) return original;
130	  }
131	  return current;
132	}
133	
134	function h(tag, attrs, ...children) {
135	  const el = document.createElement(tag);
136	  if (attrs) for (const [k, v] of Object.entries(attrs)) {
137	    if (v === null || v === undefined) continue;
138	    if (k === "class") el.className = v;
139	    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
140	    else el.setAttribute(k, v);
141	  }
142	  for (const child of children.flat()) {
143	    if (child === null || child === undefined) continue;
144	    el.append(child.nodeType ? child : document.createTextNode(String(child)));
145	  }
146	  return el;
147	}
148	
149	/* ---------- 问卷表单（新建 / 编辑共用） ---------- */
150	
151	function buildSurveyForm(existing, hooks, view) {
152	  // 新建表单首次创建成功且等待期间仍有未保存修改时，会就地转为“编辑刚创建
153	  // 的那份草稿”，因此 mode 允许从 create 切换为 edit。
154	  let mode = existing ? "edit" : "create";
155	
156	  // 表单当前正在编辑的草稿编号：编辑模式一开始就有；新建模式只在首次创建
157	  // 成功后才拿到。拿到编号之后，这份表单继续保存时一律 PUT 同一编号，不
158	  // 能再 POST 出第二份问卷。
159	  let surveyId = existing ? existing.id : null;
160	
161	  const banner = h("div", {class: "banner", id: "form-banner"});
162	  banner.hidden = true;
163	
164	  // 保存结果的状态条：成功保存与“仍有未保存修改”必须分开展示，不能只给
165	  // 一条笼统的“保存成功”。新建模式首次保存成功且等待期间没有新改动时直接
166	  // 进入详情（状态条不可见）；等待期间又有改动时则与编辑模式共用本状态条。
167	  const statusBar = h("div", {class: "save-status", id: "save-status", role: "status"});
168	  statusBar.hidden = true;
169	
170	  const titleInput = h("textarea", {id: "survey-title", rows: "1", class: "grow",
171	    maxlength: "200", placeholder: "请输入问卷标题（可含换行）"});
172	  const titleErr = h("p", {class: "field-err", id: "title-err"});
173	  const descArea = h("textarea", {id: "survey-desc", rows: "4", placeholder: "问卷说明（可留空，支持中文、引号与换行）"});
174	  const qBox = h("div", {id: "questions"});
175	  const qErr = h("p", {class: "field-err", id: "questions-err"});
176	
177	  function renumber() {
178	    const cards = qBox.querySelectorAll(".q-card");
179	    cards.forEach((card, i) => {
180	      card.querySelector(".q-index").textContent = `第 ${i + 1} 题`;
181	      card.querySelectorAll(".opt-row").forEach((row, j) => {
182	        row.querySelector(".opt-index").textContent = `选项 ${j + 1}`;
183	      });
184	    });
185	  }
186	
187	  // textarea 的高度随内容变化：单行内容外观与原输入框一致，出现内部换行时
188	  // 自动增高，让换行真实可见、可编辑，而不是被折叠或截断。
189	  function autoGrow(el) {
190	    el.style.height = "auto";
191	    el.style.height = `${el.scrollHeight}px`;
192	  }
193	  // 预填值时元素可能还没挂到文档上（scrollHeight 为 0），延到下一帧布局后再量。
194	  function scheduleGrow(el) { requestAnimationFrame(() => autoGrow(el)); }
195	
196	  function optionRow(value) {
197	    const text = h("textarea", {rows: "1", class: "opt-text grow", placeholder: "选项内容（可含换行）"});
198	    text.addEventListener("input", () => autoGrow(text));
199	    if (value !== undefined && value !== null) {
200	      // 必须在写入 .value 之前记录原稿：赋值一旦发生，CRLF/CR 就已被浏览器
201	      // 归一化成 LF，之后再读 text.value 也拿不回原始换行形式。
202	      if (mode === "edit") rememberOriginal(text, value);
203	      text.value = value; scheduleGrow(text);
204	    }
205	    const row = h("div", {class: "opt-row"},
206	      h("span", {class: "opt-index"}, "选项"),
207	      text,
208	      h("button", {type: "button", class: "link danger", onclick: () => { row.remove(); renumber(); }}, "删除")
209	    );
210	    return row;
211	  }
212	
213	  function addQuestion(type, prefill) {
214	    const isChoice = type === "single_choice";
215	    const options = h("div", {class: "options"});
216	    const card = h("div", {class: "card q-card", "data-type": type},
217	      h("div", {class: "q-head"},
218	        h("span", {class: "q-index"}, "第 N 题"),
219	        h("span", {class: "tag q-type-tag"}, isChoice ? "单选题" : "文本题"),
220	        h("label", {class: "req"},
221	          h("input", {type: "checkbox", class: "q-required"}), "必填（默认非必填）"),
222	        h("span", {class: "spacer"}),
223	        h("button", {type: "button", class: "link danger", onclick: () => { card.remove(); renumber(); }}, "删除本题")
224	      ),
225	      h("textarea", {rows: "1", class: "q-title grow", placeholder: "题目标题（可含换行）"}),
226	      h("p", {class: "field-err q-title-err"})
227	    );
228	    if (isChoice) {
229	      const saved = prefill && Array.isArray(prefill.options) ? prefill.options : null;
230	      if (saved && saved.length) saved.forEach(value => options.append(optionRow(value)));
231	      else options.append(optionRow(), optionRow());
232	      card.append(
233	        options,
234	        h("p", {class: "field-err opt-err"}),
235	        h("button", {type: "button", class: "link add-opt"}, "添加选项")
236	      );
237	      card.querySelector(".add-opt").addEventListener("click", () => {
238	        options.append(optionRow());
239	        renumber();
240	        options.querySelector(".opt-row:last-child .opt-text").focus();
241	      });
242	    }
243	    const qTitleEl = card.querySelector(".q-title");
244	    qTitleEl.addEventListener("input", () => autoGrow(qTitleEl));
245	    if (prefill) {
246	      // 与选项同理：在 .value 赋值（会把 CRLF/CR 归一化成 LF）之前先记住原稿。
247	      if (mode === "edit" && prefill.title != null) rememberOriginal(qTitleEl, prefill.title);
248	      qTitleEl.value = prefill.title != null ? prefill.title : "";
249	      card.querySelector(".q-required").checked = !!prefill.required;
250	    }
251	    scheduleGrow(qTitleEl);
252	    qBox.append(card);
253	    renumber();
254	    if (!prefill) qTitleEl.focus();
255	    return card;
256	  }
257	
258	  function clearErrors() {
259	    banner.hidden = true;
260	    banner.replaceChildren();
261	    titleErr.textContent = "";
262	    qErr.textContent = "";
263	    qBox.querySelectorAll(".invalid").forEach(el => el.classList.remove("invalid"));
264	    qBox.querySelectorAll(".field-err").forEach(el => { el.textContent = ""; });
265	  }
266	
267	  function hideSaveStatus() {
268	    statusBar.hidden = true;
269	    statusBar.replaceChildren();
270	  }
271	
272	  // 保存成功后：绿色块只陈述“刚才提交的内容已保存”；若等待期间又有修改，
273	  // 再追加一块黄色“当前还有未保存的修改”。两者同时出现、含义互不混淆。
274	  function renderSaveStatus(dirty) {
275	    statusBar.replaceChildren(
276	      h("div", {class: "save-note saved", id: "save-note-saved"},
277	        h("strong", null, "已保存：刚才提交的内容已保存到服务器。")),
278	      dirty
279	        ? h("div", {class: "save-note dirty", id: "save-note-dirty"},
280	            h("strong", null,
281	              "当前还有未保存的修改：页面内容在点击保存后又被改动（等待结果期间的修改不会自动补交）。可继续编辑，并再次点击“保存修改”。"))
282	        : null
283	    );
284	    statusBar.hidden = false;
285	  }
286	
287	  // 一次保存进行中：保存按钮禁用并明确显示“正在保存…”，状态条显示等待提示。
288	  // 在请求有明确结果前，重复点击按钮或用键盘再次提交都不会追加请求，也不会
289	  // 清掉等待提示。等待期间标题、说明、题目、选项、必填与增删操作全部可用。
290	  let saving = false;
291	  function setSavingUI() {
292	    submitButton.disabled = true;
293	    submitButton.textContent = "正在保存…";
294	    statusBar.replaceChildren(
295	      h("div", {class: "save-note saving", id: "save-note-saving", role: "status"},
296	        h("strong", null, "正在保存：正在等待本次保存的结果，请稍候。等待期间仍可继续编辑，这些改动不会自动追加到本次提交。"))
297	    );
298	    statusBar.hidden = false;
299	  }
300	  function resetSaveButton() {
301	    submitButton.disabled = false;
302	    submitButton.textContent = submitButton.getAttribute("data-label");
303	  }
304	
305	  // 整份草稿的唯一整理入口：保存时提交的内容、保存前的校验、编辑页判断
306	  // “等待保存期间是否又有修改”都从这里取数，规则只维护这一份。标题/题目
307	  // 标题/选项只按接口规则（apiTrim，与 Python strip 一致）去掉首尾空白，
308	  // 说明与内部换行原样保留；题目与选项按页面当前顺序记录，必填勾选原样。
309	  // 编辑模式下未改动的字段（含“改过又恢复”）由 resolveFieldValue 还原为
310	  // 打开时从接口读到的原稿，使内部 CRLF/CR/LF 不被浏览器的换行归一化改写；
311	  // 真正改动的字段与新建模式一律采用当前输入（浏览器中只会是 LF）。
312	  // 每次调用都返回新建的独立对象（后续输入不会改变已返回的快照），可直接
313	  // 做整体相等比较：改过又恢复原值时结构相同，不会被当成有未保存修改。
314	  function readDraft() {
315	    return {
316	      title: apiTrim(resolveFieldValue(titleInput, {trimFields: true})),
317	      description: resolveFieldValue(descArea),
318	      questions: [...qBox.querySelectorAll(".q-card")].map(card => ({
319	        type: card.dataset.type,
320	        title: apiTrim(resolveFieldValue(card.querySelector(".q-title"), {trimFields: true})),
321	        required: card.querySelector(".q-required").checked,
322	        options: [...card.querySelectorAll(".opt-text")]
323	          .map(el => apiTrim(resolveFieldValue(el, {trimFields: true})))
324	      }))
325	    };
326	  }
327	
328	  function sameState(a, b) { return JSON.stringify(a) === JSON.stringify(b); }
329	
330	  function showBanner(items) {
331	    banner.replaceChildren(h("strong", null, "问卷未能保存，请修改后重试："), h("ul", null,
332	      items.map(it => h("li", null, h("button", {type: "button", onclick: () => it.el && it.el.focus()}, it.msg)))));
333	    banner.hidden = false;
334	    banner.scrollIntoView({behavior: "smooth", block: "nearest"});
335	  }
336	
337	  const actionButtons = [
338	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("text")}, "添加文本题"),
339	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("single_choice")}, "添加单选题"),
340	    h("span", {class: "spacer"})
341	  ];
342	  if (mode === "edit") {
343	    // 离开编辑页即丢弃全部未保存的增删与输入
344	    actionButtons.push(h("a", {class: "btn secondary", href: `#/surveys/${existing.id}`}, "取消"));
345	  }
346	  const submitLabel = mode === "edit" ? "保存修改" : "保存整份问卷";
347	  const submitButton = h("button", {type: "submit", class: "btn", "data-label": submitLabel}, submitLabel);
348	  actionButtons.push(submitButton);
349	
350	  const form = h("form", {id: "draft-form", onsubmit: submitForm},
351	    banner,
352	    statusBar,
353	    h("section", null,
354	      h("h2", null, mode === "edit" ? `编辑问卷草稿 #${existing.id}` : "新建问卷草稿"),
355	      mode === "edit"
