465	        problems.push({el: titleEl, msg: `${loc}：题目标题不能为空。`});
466	      }
467	      if (question.type === "single_choice") {
468	        const optInputs = [...card.querySelectorAll(".opt-text")];
469	        const optErr = card.querySelector(".opt-err");
470	        const seen = new Set();
471	        question.options.forEach((val, j) => {
472	          if (!val) {
473	            optInputs[j].classList.add("invalid");
474	            optErr.textContent = `${loc}：第 ${j + 1} 个选项不能为空。`;
475	            problems.push({el: optInputs[j], msg: `${loc}：第 ${j + 1} 个选项不能为空。`});
476	          } else if (seen.has(val)) {
477	            optInputs[j].classList.add("invalid");
478	            optErr.textContent = `${loc}：选项“${val}”与同题其他选项重复。`;
479	            problems.push({el: optInputs[j], msg: `${loc}：选项“${val}”重复。`});
480	          }
481	          seen.add(val);
482	        });
483	        if (question.options.length < 2) {
484	          optErr.textContent = `${loc}：单选题至少需要两个选项。`;
