537	        : `网络错误，问卷尚未保存：${err}`}]);
538	      return;
539	    }
540	    if (submitView !== activeView) return;
541	    let data = {};
542	    try { data = await resp.json(); } catch (_) { /* 保留已输入内容 */ }
543	    if (submitView !== activeView) return;
544	    const saved = creating ? resp.status === 201 : resp.status === 200;
545	    if (saved && data.id !== undefined) {
546	      if (creating) {
