760	  const editMatch = location.hash.match(/^#\/surveys\/(\d+)\/edit$/);
761	  const detailMatch = location.hash.match(/^#\/surveys\/(\d+)$/);
762	  if (editMatch) renderEdit(Number(editMatch[1]));
763	  else if (detailMatch) renderDetail(Number(detailMatch[1]));
764	  else renderHome();
765	}
766	window.addEventListener("hashchange", route);
767	route();
768	</script>
769	</html>
770	"""
771	
772	
773	def validate_survey(obj):
774	    """Validate a decoded survey payload.
775	
776	    Returns (clean_survey, None) on success or (None, error_message) on failure.
777	    Strings are stored trimmed of surrounding whitespace; description keeps its
778	    raw value so Chinese, quotes and newlines are preserved.
779	    """
780	    if not isinstance(obj, dict):
781	        return None, "请求体必须是 JSON 对象"
782	    if "title" not in obj:
783	        return None, "缺少字段 title"
784	    title = obj["title"]
785	    if not isinstance(title, str):
786	        return None, "title 必须是字符串"
787	    title = title.strip()
788	    if not title:
789	        return None, "title 不能为空（或全为空白字符）"
790	
791	    description = obj.get("description", "")
792	    if not isinstance(description, str):
793	        return None, "description 必须是字符串"
794	
795	    if "questions" not in obj:
796	        return None, "缺少字段 questions"
797	    raw_questions = obj["questions"]
798	    if not isinstance(raw_questions, list):
799	        return None, "questions 必须是数组"
800	    if len(raw_questions) == 0:
801	        return None, "questions 至少需要一道题"
802	
803	    questions = []
804	    for index, raw_question in enumerate(raw_questions, start=1):
805	        location = f"第 {index} 题"
806	        if not isinstance(raw_question, dict):
807	            return None, f"{location}（questions[{index - 1}]）必须是对象"
808	
809	        if "type" not in raw_question:
810	            return None, f"{location}：缺少字段 type"
811	        question_type = raw_question["type"]
812	        if not isinstance(question_type, str):
813	            return None, f"{location}：type 必须是字符串"
814	        if question_type not in QUESTION_TYPES:
815	            shown = json.dumps(question_type, ensure_ascii=False)
816	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
817	
818	        if "title" not in raw_question:
819	            return None, f"{location}：缺少字段 title"
820	        question_title = raw_question["title"]
821	        if not isinstance(question_title, str):
822	            return None, f"{location}：title 必须是字符串"
823	        question_title = question_title.strip()
824	        if not question_title:
825	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
826	
827	        required = raw_question.get("required", False)
828	        if not isinstance(required, bool):
829	            return None, f"{location}：required 必须是布尔值"
830	
831	        raw_options = raw_question.get("options", [])
832	        if not isinstance(raw_options, list):
833	            return None, f"{location}：options 必须是数组"
834	
835	        options = []
836	        if question_type == "text":
837	            if len(raw_options) > 0:
838	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
839	        else:
840	            if len(raw_options) < 2:
841	                return None, f"{location}：单选题至少需要两个选项"
842	            seen = set()
843	            for option_index, raw_option in enumerate(raw_options, start=1):
844	                if not isinstance(raw_option, str):
845	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
846	                option = raw_option.strip()
847	                if not option:
848	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
849	                if option in seen:
850	                    shown = json.dumps(option, ensure_ascii=False)
851	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
852	                seen.add(option)
853	                options.append(option)
854	
855	        questions.append({
856	            "type": question_type,
857	            "title": question_title,
858	            "required": required,
859	            "options": options,
860	        })
861	
862	    return {
863	        "title": title,
864	        "description": description,
865	        "questions": questions,
866	    }, None
867	
