869	def main():
870	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
871	    commands = parser.add_subparsers(dest="command", required=True)
872	    serve = commands.add_parser("serve", help="Start the HTTP service")
873	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
874	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
875	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
876	    args = parser.parse_args()
877	    if not 0 <= args.port <= 65535:
878	        parser.error("port must be between 0 and 65535")
879	    args.data_dir.mkdir(parents=True, exist_ok=True)
880	    # 每个连接由独立线程处理（见下方 ThreadingHTTPServer），因此数据库连接
881	    # 会被多个线程共享：check_same_thread=False 允许跨线程使用，所有读写再
882	    # 经 db_lock 串行化，保证一次保存/替换内部的多条语句仍然原子生效。
883	    database = sqlite3.connect(args.data_dir / "open-survey.sqlite", check_same_thread=False)
884	    db_lock = threading.Lock()
885	    database.execute("CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY, title TEXT NOT NULL)")
886	    columns = {row[1] for row in database.execute("PRAGMA table_info(surveys)")}
887	    if "description" not in columns:
888	        database.execute("ALTER TABLE surveys ADD COLUMN description TEXT NOT NULL DEFAULT ''")
889	    database.execute(
890	        "CREATE TABLE IF NOT EXISTS questions ("
891	        "id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL, position INTEGER NOT NULL, "
892	        "type TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL)"
893	    )
894	    database.execute(
895	        "CREATE TABLE IF NOT EXISTS question_options ("
896	        "id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL)"
897	    )
898	    database.commit()
899	
900	    def survey_detail(survey_id):
901	        with db_lock:
902	            row = database.execute(
903	                "SELECT title, COALESCE(description, '') FROM surveys WHERE id = ?",
904	                (survey_id,),
905	            ).fetchone()
906	            if row is None:
907	                return None
908	            title, description = row
909	            questions = []
910	            question_rows = database.execute(
911	                "SELECT id, type, title, required FROM questions WHERE survey_id = ? ORDER BY position",
912	                (survey_id,),
913	            ).fetchall()
914	            for question_id, question_type, question_title, required in question_rows:
915	                options = [option_row[0] for option_row in database.execute(
916	                    "SELECT text FROM question_options WHERE question_id = ? ORDER BY position",
917	                    (question_id,),
918	                )]
919	                questions.append({
920	                    "type": question_type,
921	                    "title": question_title,
922	                    "required": bool(required),
923	                    "options": options,
924	                })
925	        return {
926	            "id": survey_id,
927	            "title": title,
928	            "description": description,
929	            "questions": questions,
930	        }
931	
932	    def save_survey(clean):
933	        """Insert the whole survey atomically; returns the new id."""
934	        with db_lock:
935	            try:
936	                cursor = database.execute(
937	                    "INSERT INTO surveys (title, description) VALUES (?, ?)",
938	                    (clean["title"], clean["description"]),
939	                )
940	                survey_id = cursor.lastrowid
941	                write_questions(survey_id, clean["questions"])
942	                database.commit()
943	                return survey_id
944	            except Exception:
945	                database.rollback()
946	                raise
947	
948	    def write_questions(survey_id, questions):
949	        """Replace all questions/options of a survey with the given ordered list."""
950	        old_question_ids = [row[0] for row in database.execute(
951	            "SELECT id FROM questions WHERE survey_id = ?", (survey_id,)
952	        )]
953	        if old_question_ids:
954	            placeholders = ",".join("?" for _ in old_question_ids)
955	            database.execute(
956	                f"DELETE FROM question_options WHERE question_id IN ({placeholders})",
957	                old_question_ids,
958	            )
959	        database.execute("DELETE FROM questions WHERE survey_id = ?", (survey_id,))
960	        for position, question in enumerate(questions):
961	            question_cursor = database.execute(
962	                "INSERT INTO questions (survey_id, position, type, title, required) "
963	                "VALUES (?, ?, ?, ?, ?)",
964	                (survey_id, position, question["type"], question["title"],
965	                 1 if question["required"] else 0),
966	            )
967	            question_id = question_cursor.lastrowid
968	            for option_position, option in enumerate(question["options"]):
969	                database.execute(
970	                    "INSERT INTO question_options (question_id, position, text) VALUES (?, ?, ?)",
971	                    (question_id, option_position, option),
972	                )
973	
974	    def replace_survey(survey_id, clean):
975	        """Replace a whole survey atomically; keeps the same id.
976	
977	        Returns False when the survey does not exist (no record is created).
978	        """
979	        with db_lock:
980	            row = database.execute("SELECT 1 FROM surveys WHERE id = ?", (survey_id,)).fetchone()
981	            if row is None:
982	                return False
983	            try:
984	                database.execute(
985	                    "UPDATE surveys SET title = ?, description = ? WHERE id = ?",
986	                    (clean["title"], clean["description"], survey_id),
987	                )
988	                write_questions(survey_id, clean["questions"])
989	                database.commit()
990	                return True
991	            except Exception:
992	                database.rollback()
993	                raise
994	
995	    class Handler(BaseHTTPRequestHandler):
996	        def respond(self, status, value, *, html=False, allow=None):
997	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
998	            self.send_response(status)
999	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
1000	            self.send_header("Content-Length", str(len(payload)))
1001	            if status == 405 and allow is not None:
1002	                self.send_header("Allow", ", ".join(allow))
1003	            self.end_headers()
1004	            self.wfile.write(payload)
1005	
1006	        def list_surveys(self):
1007	            with db_lock:
1008	                records = [
1009	                    {"id": row[0], "title": row[1]}
1010	                    for row in database.execute("SELECT id, title FROM surveys ORDER BY id")
1011	                ]
1012	            self.respond(200, {RESOURCE: records})
1013	
1014	        def read_payload(self):
1015	            """Read and decode a JSON request body.
1016	
1017	            Returns (payload, None) or (None, error_message).
1018	            """
1019	            try:
1020	                length = int(self.headers.get("Content-Length") or 0)
1021	            except ValueError:
1022	                length = -1
1023	            if length < 0:
1024	                return None, "Content-Length 无效"
1025	            if length > MAX_BODY_BYTES:
1026	                return None, "请求体过大"
1027	            body = self.rfile.read(length) if length else b""
1028	            try:
1029	                return json.loads(body.decode("utf8")), None
1030	            except (UnicodeDecodeError, json.JSONDecodeError) as error:
1031	                return None, f"请求体不是合法 JSON：{error}"
1032	
1033	        def create_survey(self):
1034	            payload, error = self.read_payload()
1035	            if error is not None:
1036	                self.respond(400, {"error": error})
1037	                return
1038	
1039	            clean, error = validate_survey(payload)
1040	            if error is not None:
1041	                self.respond(400, {"error": error})
1042	                return
1043	            try:
1044	                survey_id = save_survey(clean)
1045	            except sqlite3.DatabaseError as error:
1046	                self.respond(500, {"error": f"保存失败：{error}"})
1047	                return
1048	            result = {"id": survey_id, **clean}
1049	            self.respond(201, result)
1050	
1051	        def update_survey(self, survey_id):
1052	            payload, read_error = self.read_payload()
1053	            if survey_detail(survey_id) is None:
1054	                # Editing a missing id is always 404 and must never create one.
1055	                self.respond(404, {"error": "not found"})
1056	                return
1057	            if read_error is not None:
1058	                self.respond(400, {"error": read_error})
1059	                return
1060	
1061	            # Full replacement: validate before touching the stored draft so a
1062	            # rejected request leaves the old survey exactly as it was.
1063	            clean, error = validate_survey(payload)
1064	            if error is not None:
1065	                self.respond(400, {"error": error})
1066	                return
1067	            try:
1068	                replace_survey(survey_id, clean)
1069	            except sqlite3.DatabaseError as error:
1070	                self.respond(500, {"error": f"保存失败：{error}"})
1071	                return
1072	            self.respond(200, {"id": survey_id, **clean})
1073	
1074	        def route(self):
1075	            location = urlsplit(self.path).path
1076	            detail_match = re.fullmatch(r"/api/surveys/(\d+)", location)
1077	
1078	            if location == "/api/surveys":
1079	                allowed = ["GET", "POST"]
1080	            elif location in ("/", "/health"):
1081	                allowed = ["GET"]
1082	            elif detail_match:
1083	                allowed = ["GET", "PUT"]
1084	            else:
1085	                self.respond(404, {"error": "not found"})
1086	                return
1087	
1088	            if self.command not in allowed:
1089	                self.respond(405, {"error": "method not allowed"}, allow=allowed)
1090	                return
1091	
1092	            if location == "/":
1093	                self.respond(200, PAGE, html=True)
1094	            elif location == "/health":
1095	                self.respond(200, {"status": "ok", "product": PRODUCT})
1096	            elif location == "/api/surveys":
1097	                if self.command == "POST":
1098	                    self.create_survey()
1099	                else:
1100	                    self.list_surveys()
1101	            else:
1102	                survey_id = int(detail_match.group(1))
1103	                if self.command == "PUT":
1104	                    self.update_survey(survey_id)
1105	                    return
1106	                detail = survey_detail(survey_id)
1107	                if detail is None:
1108	                    self.respond(404, {"error": "not found"})
1109	                else:
1110	                    self.respond(200, detail)
1111	
1112	        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_HEAD = do_OPTIONS = route
1113	
1114	    def stop(_signal, _frame):
1115	        raise KeyboardInterrupt
1116	
1117	    signal.signal(signal.SIGTERM, stop)
1118	    server = None
1119	    try:
1120	        # 每个连接在独立线程中处理：浏览器预先建立但暂不发送请求的备用连接、
1121	        # 或只发了部分请求头/正文就暂停的连接，只会占用自己的线程，不会拖住
1122	        # 其他连接上的完整请求。daemon_threads 保证退出时不被这些空闲连接卡住。
1123	        server = ThreadingHTTPServer((args.host, args.port), Handler)
1124	        host, port = server.server_address[:2]
1125	        address = f"[{host}]" if ":" in host else host
1126	        print(f"{PRODUCT} listening on http://{address}:{port}", flush=True)
1127	        server.serve_forever()
1128	    except KeyboardInterrupt:
1129	        pass
1130	    finally:
1131	        if server is not None:
1132	            server.server_close()
1133	        database.close()
