        self.assertEqual(snapshot["title"], "校验失败时的标题")
        self.assert_server_unchanged(survey_id, before)

    def test_normal_wait_network_error_stays_and_keeps_all_edits(self):
        """没有离开时：网络失败停在编辑页、显示网络错误，新增/删除的题目与选项全部保留。"""
