            if event.get("method") == "Page.loadEventFired":
                loaded = True
            else:
                # 导航期间首页就会发起初次列表读取，其 Fetch.requestPaused
                # 事件不能在这里丢弃，放回队列交给后台事件循环挂起。
                leftover.append(event)
        if leftover:
            self.ws.push_events(leftover)
        if loaded:
            return
    raise AssertionError(f"页面加载超时：{url}")

